<?php
require __DIR__ . '/_boot.php'; $pageTitle='Categories'; $pageDescription='Give every bloom a place in the catalog.'; $headingAction=['path'=>'/admin/category-edit.php','label'=>'+ Add category'];
$categories=db()->query('SELECT c.*,COUNT(p.id) AS product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id,c.name,c.created_at ORDER BY c.name')->fetchAll();
require dirname(__DIR__, 2) . '/templates/admin_header.php';
?>
<section class="panel"><?php if (!$categories): ?><div class="empty-state"><h2>A blank canvas for your flowers.</h2><p>Add your first category to organize the catalog.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Arrangements</th><th>Actions</th></tr></thead><tbody><?php foreach ($categories as $category): ?><tr><td><?= e($category['name']) ?></td><td><?= (int)$category['product_count'] ?></td><td><div class="row-actions"><a href="<?= e(url('/admin/category-edit.php?id=' . $category['id'])) ?>">Edit</a><?php if (!$category['product_count']): ?><form method="post" action="<?= e(url('/admin/actions/category-delete.php')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$category['id'] ?>"><button type="submit" class="text-button danger">Delete</button></form><?php else: ?><small>In use</small><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><p class="help-text">Categories containing active or archived arrangements cannot be deleted.</p>
<?php require dirname(__DIR__, 2) . '/templates/admin_footer.php'; ?>
